/-- Extract distinct block responses by averaging identical recipient outcomes. -/
def distinctResponses (o : Record (Fin n)) : Fin B → ℝ :=
  fun ℓ => (d : ℝ)⁻¹ * ∑ i ∈ recipientBlock n B d ℓ, o.2.2 i

/-- The order-weighted nonconstant Walsh channel energy. -/
def etaOne (d : ℕ) (h : ℝ) : ℝ :=
  ∑ s ∈ Finset.Icc 1 d, s * (d.choose s : ℝ) * gamma d h s

/-- The squared Walsh coefficient integrated against its reference density. -/
def gamma (d : ℕ) (h : ℝ) (s : ℕ) : ℝ :=
  ∫ w, (walshCoeff d h s w) ^ 2 * refDensity d h w

/-- The off-diagonal treatment sources of a recipient. -/
def inNbhd (θ : Schedule V) (i : V) : Finset V :=
  Finset.univ.filter (fun j => θ.edge j i)

