/-- The compulsory own coordinate adjoined to the off-diagonal sources. -/
-- @node: oracleNbhd
def oracleNbhd (θ : Schedule V) (i : V) : Finset V := insert i (inNbhd θ i)

/-- The additive potential outcome. -/
def potentialOutcome (θ : Schedule V) (i : V) (z : V → Bool) : ℝ :=
  θ.a i + θ.t i * treatment (z i) + ∑ j ∈ inNbhd θ i, θ.b i j * treatment (z j)

/-- The published in-neighborhood, including diagonal arrows when present. -/
def pubNbhd (ϑ : PublishedSchedule V) (i : V) : Finset V :=
  Finset.univ.filter (fun j => ϑ.edge j i)

/-- The published out-neighborhood, including diagonal arrows when present. -/
def pubOutNbhd (ϑ : PublishedSchedule V) (j : V) : Finset V :=
  Finset.univ.filter (fun i => ϑ.edge j i)

/-- The published raw-monomial polynomial potential outcome, including the empty monomial. -/
def pubOutcome (ϑ : PublishedSchedule V) (i : V) (z : Assign V) : ℝ :=
  ∑ S ∈ (pubNbhd ϑ i).powerset, ϑ.coef i S * ∏ j ∈ S, treatment (z j)

/-- The recipient block in the second half of the bipartite layout. -/
def recipientBlock (ℓ : Fin B) : Finset (Fin n) := -- @realizes ell(Fin B; paper label ℓ.val+1)
  Finset.univ.filter (fun i => B * d + ℓ.val * d ≤ i.val ∧ i.val < B * d + (ℓ.val + 1) * d)

/-- The recorded sources of a recipient, read solely from the observed record. -/
def recordedNbhd (H : OffDiag V → Bool) (i : V) : Finset V :=
  Finset.univ.filter (fun j => ∃ hji : j ≠ i, H ⟨(j, i), hji⟩ = true)

/-- The uniform average of all sign-vector row densities. -/
def refDensity (d : ℕ) (h : ℝ) (w : ℝ) : ℝ :=
  ((2 : ℝ) ^ d)⁻¹ * ∑ ε : Fin d → Bool, rowDensity d h ε w

/-- Remove known diagonal arrows while preserving all assignments and outcomes. -/
def removeRecord (o : AugRecord V) : Record V :=
  (fun e => o.1.1 e.1, o.2)

/-- The actual marginal law of the detailed labeled retained graph. -/
def retainedGraphMarginal (D : Measure (Assign (Fin n) × Audit (Fin n))) :
    Measure (OffDiag (Fin n) → Bool) := (graphAssignMarginal n B d D).map Prod.fst

/-- The number of revealed labeled sources in a recipient block. -/
def revealedCount (H : OffDiag (Fin n) → Bool) (ℓ : Fin B) : ℕ :=
  (revealedSources n B d H ℓ).card

/-- The sum of observed treatment signs over the revealed labeled sources. -/
def revealedSignSum (H : OffDiag (Fin n) → Bool) (z : Assign (Fin n)) (ℓ : Fin B) : ℝ :=
  ∑ j ∈ revealedSources n B d H ℓ, signOf (z j)

/-- A single-row shifted baseline density for a fixed Boolean sign vector. -/
def rowDensity (d : ℕ) (h : ℝ) (ε : Fin d → Bool) (w : ℝ) : ℝ :=
  cosSqDensity (w - h / (2 * d) * ∑ j, signOf (ε j))

/-- Extended nonnegative squared loss avoids nonintegrable-real-integral junk values. -/
def sqLoss (D : Measure (Assign V × Audit V)) (θ : Schedule V) (T : Estimator V) : ℝ≥0∞ :=
  ∫⁻ x, ENNReal.ofReal ((T.1 x - tte θ) ^ 2) ∂(recordLaw D θ)

/-- The true off-diagonal graph as a labeled Boolean array. -/
def suppliedGraphOf (θ : Schedule V) : OffDiag V → Bool :=
  fun e => decide (θ.edge e.1.1 e.1.2)

/-- The original record and the supplied true graph under one design realization. -/
def suppliedRecordOf (θ : Schedule V) (ω : Assign V × Audit V) : SuppliedRecord V :=
  (recordOf θ ω, suppliedGraphOf θ)

/-- Symmetric sign polynomial on a Boolean slice. -/
def symmetricSignPoly (M k : ℕ) (z : Fin M → Bool) : ℝ :=
  (M.choose k : ℝ)⁻¹ * ∑ E ∈ Finset.univ.powersetCard k, ∏ j ∈ E, signOf (z j)

/-- The nonlocal testing scale is clipped at one and equals one when no association is retained. -/
def testingScale (B d : ℕ) (q : ℝ) : ℝ :=
  if 0 < retentionP d q then min 1 ((d : ℝ) / Real.sqrt ((B * d : ℕ) * retentionP d q)) else 1

/-- The canonical independent assignment-audit product design. -/
def thinnedDesign (q : ℝ) : Measure (Assign V × Audit V) :=
  (halfBernoulli V).prod (auditLaw V q)

/-- The measurable seeded representative of the total upper rule. -/
def upperEstimator (n d : ℕ) (q : ℝ) : Estimator V :=
  ⟨fun x => upperRule n d q x.1, upperRule_seeded_measurable n d q⟩
